import {useLiveQuery} from 'dexie-react-hooks'; import {useState} from 'react'; import {db} from '../services/db'; import {saveProduct} from '../services/inventory'; import type {User} from '../types/models'; import {money} from '../utils/ids';
const labels:any={arabic_name:'اسم الدواء',english_name:'الاسم الإنجليزي',generic_name:'الاسم العلمي',barcode:'الباركود',sku:'رمز الصنف',category:'الفئة',manufacturer:'الشركة المصنعة',purchase_price:'سعر الشراء',selling_price:'سعر البيع',reorder_level:'حد إعادة الطلب'};
export default function Products({user}:{user:User}){const rows=useLiveQuery(()=>db.products.toArray(),[])||[]; const empty={arabic_name:'',barcode:'',purchase_price:0,selling_price:0,reorder_level:0,tax:0,active:true}; const [f,setF]=useState<any>(empty); async function save(e:any){e.preventDefault(); await saveProduct(user.id,{...f,purchase_price:+f.purchase_price,selling_price:+f.selling_price,reorder_level:+f.reorder_level,tax:+(f.tax||0),active:f.active!==false}); setF(empty)} async function toggle(id:string,active:boolean){await db.products.update(id,{active,updated_at:new Date().toISOString()})} return <section><h1>المنتجات</h1><form className="card formgrid" onSubmit={save}>{['arabic_name','english_name','generic_name','barcode','sku','category','manufacturer','purchase_price','selling_price','reorder_level'].map(k=><input key={k} value={f[k]||''} onChange={e=>setF({...f,[k]:e.target.value})} placeholder={labels[k]||k}/>) }<button>{f.id?'حفظ التعديل':'حفظ المنتج'}</button>{f.id&&<button type="button" className="ghost" onClick={()=>setF(empty)}>إلغاء التعديل</button>}</form><div className="card"><table><thead><tr><th>الاسم</th><th>باركود</th><th>شراء</th><th>بيع</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody>{rows.map(p=><tr key={p.id}><td>{p.arabic_name}</td><td>{p.barcode}</td><td>{money(p.purchase_price)}</td><td>{money(p.selling_price)}</td><td><span className={`status ${p.active?'ok':'bad'}`}>{p.active?'نشط':'غير نشط'}</span></td><td><button onClick={()=>setF(p)}>تعديل</button><button className="ghost" onClick={()=>toggle(p.id,!p.active)}>{p.active?'تعطيل':'تفعيل'}</button></td></tr>)}</tbody></table>{!rows.length&&<p className="empty">لا توجد منتجات بعد.</p>}</div></section>}
