import React from 'react';
export default class ErrorBoundary extends React.Component<{children:React.ReactNode},{err:Error|null}>{state:{err:Error|null}={err:null}; static getDerivedStateFromError(err:Error){return{err}}; render(){ if(this.state.err)return <div className="error"><h2>حدث خطأ غير متوقع</h2><p>بيانات الصيدلية المحلية ما زالت آمنة. حاول تحديث الصفحة أو الرجوع للقائمة الرئيسية.</p><code>{this.state.err.message}</code></div>; return this.props.children; }}
