import { db } from './db';

function esc(value: unknown) {
  return String(value ?? '').replace(/[&<>"]/g, (m) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[m]!));
}

export async function printInvoice(saleId: string) {
  const sale = await db.sales.get(saleId);
  if (!sale) throw new Error('الفاتورة غير موجودة');
  const [items, settings, customer, user] = await Promise.all([
    db.sale_items.where('sale_id').equals(saleId).toArray(),
    db.settings.get('settings'),
    sale.customer_id ? db.customers.get(sale.customer_id) : Promise.resolve(undefined),
    db.users.get(sale.cashier_id),
  ]);
  const products = await db.products.bulkGet(items.map((i) => i.product_id));
  const rows = items.map((it, idx) => {
    const p = products[idx];
    return `<tr><td>${idx + 1}</td><td>${esc(p?.arabic_name || p?.english_name || it.product_id)}</td><td>${it.quantity}</td><td>${it.unit_price.toFixed(2)}</td><td>${it.discount.toFixed(2)}</td><td>${it.line_total.toFixed(2)}</td></tr>`;
  }).join('');
  const html = `<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>فاتورة ${esc(sale.invoice_no)}</title><style>
  *{box-sizing:border-box}body{font-family:Arial,Tahoma,sans-serif;margin:0;background:#f3f4f6;color:#111}.toolbar{position:sticky;top:0;background:#111827;color:#fff;padding:12px;display:flex;gap:8px;justify-content:center}.toolbar button{border:0;border-radius:8px;padding:10px 16px;font-weight:700;cursor:pointer}.print{background:#0f766e;color:white}.close{background:#374151;color:white}.sheet{width:210mm;min-height:297mm;margin:18px auto;background:#fff;padding:16mm;box-shadow:0 6px 30px #0002}.head{display:flex;justify-content:space-between;gap:24px;align-items:flex-start;border-bottom:3px solid #111;padding-bottom:14px}.brand{display:flex;gap:12px;align-items:center}.brand img{width:72px;height:72px;object-fit:contain}.no-logo{width:72px;height:72px;border:1px dashed #cbd5e1;border-radius:10px;display:grid;place-items:center;color:#94a3b8;font-size:11px;text-align:center}.brand h1{margin:0;font-size:24px}.muted{color:#6b7280;font-size:12px;line-height:1.7}.box{background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:10px;margin:16px 0;display:grid;grid-template-columns:repeat(3,1fr);gap:8px}table{width:100%;border-collapse:collapse;margin-top:14px}th{background:#111;color:white}td,th{padding:10px;border-bottom:1px solid #e5e7eb;text-align:right;font-size:13px}.totals{width:45%;margin-right:auto;margin-top:16px;border:1px solid #e5e7eb}.totals div{display:flex;justify-content:space-between;padding:9px 12px;border-bottom:1px solid #e5e7eb}.totals b{background:#111;color:white}.footer{text-align:center;color:#6b7280;border-top:1px solid #e5e7eb;margin-top:36px;padding-top:14px;font-size:12px}@media(max-width:800px){.sheet{width:100%;min-height:auto;margin:0;padding:14px}.box{grid-template-columns:1fr}.totals{width:100%}.toolbar{bottom:0;top:auto;position:fixed;width:100%;z-index:9}}@media print{body{background:white}.toolbar{display:none}.sheet{box-shadow:none;margin:0;width:100%;min-height:auto}@page{size:A4;margin:8mm}}
  </style></head><body><div class="toolbar"><button class="print" onclick="window.print()">طباعة الفاتورة</button><button class="close" onclick="window.close()">إغلاق</button></div><main class="sheet"><section class="head"><div class="brand">${settings?.logo ? `<img src="${settings.logo}" alt="شعار الصيدلية">` : `<div class="no-logo">شعار الصيدلية</div>`}<div><h1>${esc(settings?.pharmacy_name || 'اسم الصيدلية')}</h1><div class="muted">${esc(settings?.address || '')}<br>${esc(settings?.phone || '')} ${settings?.email ? ' — ' + esc(settings.email) : ''}<br>${settings?.tax_number ? 'الرقم الضريبي: ' + esc(settings.tax_number) : ''}</div></div></div><div><h2>فاتورة بيع</h2><div class="muted">رقم الفاتورة: ${esc(sale.invoice_no)}<br>التاريخ: ${new Date(sale.created_at).toLocaleString('ar')}<br>الحالة: ${sale.status === 'COMPLETED' ? 'مكتملة' : sale.status === 'CANCELLED' ? 'ملغاة' : 'مرتجعة'}</div></div></section><section class="box"><div>العميل: <b>${esc(customer?.name || 'نقدي')}</b></div><div>الكاشير: <b>${esc(user?.name || '')}</b></div><div>طريقة الدفع: <b>${sale.payment_method === 'Cash' ? 'نقدي' : sale.payment_method}</b></div></section><table><thead><tr><th>#</th><th>الصنف</th><th>الكمية</th><th>السعر</th><th>الخصم</th><th>الإجمالي</th></tr></thead><tbody>${rows}</tbody></table><section class="totals"><div><span>المجموع الفرعي</span><span>${sale.subtotal.toFixed(2)}</span></div><div><span>الخصم</span><span>${sale.discount.toFixed(2)}</span></div><div><span>الضريبة</span><span>${sale.tax.toFixed(2)}</span></div><div><b>الإجمالي</b><b>${sale.total.toFixed(2)} ${esc(settings?.currency_symbol || '')}</b></div><div><span>المدفوع</span><span>${sale.paid.toFixed(2)}</span></div><div><span>المتبقي</span><span>${sale.remaining.toFixed(2)}</span></div></section><div class="footer">${esc(settings?.invoice_footer || 'شكراً لتعاملكم معنا')}<br><small>النظام بواسطة النجاح لإدارة الصيدليات — 0121164581 — واتساب 0969696787</small></div></main></body></html>`;
  const win = window.open('', '_blank');
  if (!win) throw new Error('المتصفح منع فتح معاينة الفاتورة. اسمح بالنوافذ المنبثقة ثم حاول مرة أخرى.');
  win.document.open();
  win.document.write(html);
  win.document.close();
}
