import {useEffect,useState} from 'react'; import {dashboardStats,series} from '../services/reports'; import {money} from '../utils/ids'; import MiniChart from '../components/MiniChart';
export default function Reports(){const [s,setS]=useState<any>(),[rows,setRows]=useState<any[]>([]); useEffect(()=>{dashboardStats().then(setS); series(30).then(setRows)},[]); return <section><h1>التقارير</h1><div className="grid cards">{Object.entries(s||{}).map(([k,v])=><div className="card stat"><span>{{todaySales:'مبيعات اليوم',todayPurchases:'مشتريات اليوم',todayProfit:'ربح اليوم',cashSales:'المبيعات النقدية',creditSales:'المبيعات الآجلة',expenses:'المصروفات',stockValue:'قيمة المخزون',customerDebts:'ديون العملاء',supplierDebts:'ديون الموردين'}[k]||k}</span><b>{money(Number(v))}</b></div>)}</div><div className="card"><h3>المبيعات والربح</h3><MiniChart/><table><thead><tr><th>التاريخ</th><th>المبيعات</th><th>المشتريات</th><th>المصروفات</th><th>الربح</th></tr></thead><tbody>{rows.map(r=><tr><td>{r.date}</td><td>{money(r.sales)}</td><td>{money(r.purchases)}</td><td>{money(r.expenses)}</td><td>{money(r.profit)}</td></tr>)}</tbody></table></div></section>}
