import {useLiveQuery} from 'dexie-react-hooks'; import {useState} from 'react'; import {db} from '../services/db'; import type {User} from '../types/models'; import {now,uid,money} from '../utils/ids';
const labels:any={name:'الاسم',phone:'رقم الهاتف',address:'العنوان',email:'البريد الإلكتروني',company:'الشركة',notes:'ملاحظات',credit_limit:'حد الدين'};
export default function People({type,user}:{type:'customers'|'suppliers';user:User}){const rows=useLiveQuery(()=>(db as any)[type].toArray(),[type])||[]; const blank={name:'',balance:0,credit_limit:0}; const [f,setF]=useState<any>(blank); async function save(e:any){e.preventDefault(); const row={pharmacy_id:user.pharmacy_id,updated_at:now(),balance:0,...f,credit_limit:+(f.credit_limit||0)}; if(f.id) await (db as any)[type].update(f.id,row); else await (db as any)[type].add({id:uid(type),created_at:now(),...row}); setF(blank)} return <section><h1>{type==='customers'?'العملاء':'الموردون'}</h1><form className="card formgrid" onSubmit={save}>{['name','phone','address','email','company','notes','credit_limit'].filter(k=>type==='suppliers'||!['company','email'].includes(k)).map(k=><input key={k} value={f[k]||''} onChange={e=>setF({...f,[k]:e.target.value})} placeholder={labels[k]||k}/>) }<button>{f.id?'حفظ التعديل':'حفظ'}</button>{f.id&&<button type="button" className="ghost" onClick={()=>setF(blank)}>إلغاء التعديل</button>}</form><div className="card"><table><thead><tr><th>الاسم</th><th>الهاتف</th><th>الرصيد</th><th>إجراءات</th></tr></thead><tbody>{rows.map((r:any)=><tr key={r.id}><td>{r.name}</td><td>{r.phone}</td><td>{money(r.balance)}</td><td><button onClick={()=>setF(r)}>تعديل</button></td></tr>)}</tbody></table></div></section>}
