import {useLiveQuery} from 'dexie-react-hooks'; import {db} from '../services/db'; import type {User} from '../types/models'; import {useState} from 'react'; import {adjustStock, saveBatch} from '../services/inventory';
export default function Inventory({user}:{user:User}){const products=useLiveQuery(()=>db.products.toArray(),[])||[]; const batches=useLiveQuery(()=>db.batches.toArray(),[])||[]; const [f,setF]=useState<any>({}); async function add(e:any){e.preventDefault(); await saveBatch(user.id,{...f,quantity:+f.quantity,initial_quantity:+f.quantity,purchase_price:+f.purchase_price,selling_price:+f.selling_price}); setF({})} return <section><h1>المخزون والتشغيلات</h1><form className="card formgrid" onSubmit={add}><select onChange={e=>setF({...f,product_id:e.target.value})}><option value="">اختر الدواء</option>{products.map(p=><option value={p.id}>{p.arabic_name}</option>)}</select>{['batch_number','quantity','purchase_price','selling_price','expiry_date'].map(k=><input key={k} type={k.includes('date')?'date':k.includes('price')||k==='quantity'?'number':'text'} value={f[k]||''} onChange={e=>setF({...f,[k]:e.target.value})} placeholder={{batch_number:'رقم التشغيلة',quantity:'الكمية',purchase_price:'سعر الشراء',selling_price:'سعر البيع',expiry_date:'تاريخ الصلاحية'}[k]||k}/>) }<button>إضافة تشغيلة</button></form><div className="card"><table><thead><tr><th>المنتج</th><th>التشغيلة</th><th>الكمية</th><th>الصلاحية</th><th>تسوية</th></tr></thead><tbody>{batches.map(b=><tr><td>{products.find(p=>p.id===b.product_id)?.arabic_name}</td><td>{b.batch_number}</td><td>{b.quantity}</td><td>{b.expiry_date}</td><td><button onClick={()=>adjustStock(user.id,b.product_id,b.id,1,'adjustment','تسوية يدوية بإضافة وحدة')}>+1</button></td></tr>)}</tbody></table></div></section>}
