import {useEffect,useState} from 'react'; import {series} from '../services/reports';
export default function MiniChart(){const [rows,setRows]=useState<any[]>([]); useEffect(()=>{series(30).then(setRows)},[]); const max=Math.max(1,...rows.map(r=>r.sales)); const pts=rows.map((r,i)=>`${i*10},${80-(r.sales/max)*70}`).join(' '); return <svg viewBox="0 0 300 90" className="chart"><polyline fill="none" stroke="#0f766e" strokeWidth="3" points={pts}/></svg>}
