import {useEffect,useRef,useState} from 'react'; import type {User,Product} from '../types/models'; import {productSearch} from '../services/inventory'; import {completeSale} from '../services/sales'; import {money} from '../utils/ids'; import {printInvoice} from '../services/invoice'; import BarcodeScanner from '../components/BarcodeScanner';
type Line={product:Product; quantity:number; discount:number};
export default function POS({user}:{user:User}){const [q,setQ]=useState(''),[results,setResults]=useState<Product[]>([]),[cart,setCart]=useState<Line[]>([]),[paid,setPaid]=useState(0),[msg,setMsg]=useState(''),[scannerOpen,setScannerOpen]=useState(false); const input=useRef<HTMLInputElement>(null); useEffect(()=>{productSearch(q).then(setResults)},[q]); function add(p:Product){setCart(c=>{const i=c.find(x=>x.product.id===p.id); return i?c.map(x=>x.product.id===p.id?{...x,quantity:x.quantity+1}:x):[...c,{product:p,quantity:1,discount:0}]}); setQ(''); input.current?.focus()} async function handleScan(code:string){setMsg(''); const found=await productSearch(code); const exact=found.find(p=>p.barcode===code||p.alternative_barcode===code)||found[0]; if(exact){add(exact); setMsg('تمت إضافة المنتج من الباركود.')} else {setQ(code); setMsg('المنتج غير موجود. يمكنك إضافته من صفحة المنتجات.')}} const total=cart.reduce((s,l)=>s+l.quantity*l.product.selling_price-l.discount,0); async function sell(){setMsg(''); try{const sale=await completeSale(user.id,cart.map(l=>({product_id:l.product.id,quantity:l.quantity,unit_price:l.product.selling_price,discount:l.discount/l.quantity,tax:l.product.tax})),paid,'Cash'); setCart([]); setPaid(0); setMsg('تم البيع بنجاح'); await printInvoice(sale.id);}catch(e:any){setMsg(e.message)}} return <section><h1>نقطة البيع</h1><div className="grid two"><div className="card"><div className="pos-tools"><button type="button" className="primary" onClick={()=>setScannerOpen(true)}>مسح بالكاميرا</button><span>أو امسح بقارئ الباركود/اكتب الرقم</span></div><input ref={input} autoFocus value={q} onChange={e=>setQ(e.target.value)} placeholder="امسح الباركود أو ابحث عن منتج" onKeyDown={e=>{if(e.key==='Enter'&&results[0])add(results[0])}}/><div className="list">{results.map(p=><button key={p.id} onClick={()=>add(p)}>{p.arabic_name} <small>{p.barcode}</small> <b>{money(p.selling_price)}</b></button>)}</div></div><div className="card"><h3>السلة</h3><table><tbody>{cart.map(l=><tr key={l.product.id}><td>{l.product.arabic_name}</td><td><input type="number" value={l.quantity} min={1} onChange={e=>setCart(c=>c.map(x=>x===l?{...x,quantity:+e.target.value}:x))}/></td><td>{money(l.product.selling_price*l.quantity)}</td><td><button onClick={()=>setCart(c=>c.filter(x=>x!==l))}>حذف</button></td></tr>)}</tbody></table><h2>الإجمالي: {money(total)}</h2><input type="number" value={paid} onChange={e=>setPaid(+e.target.value)} placeholder="المدفوع"/><p>المتبقي: {money(Math.max(0,total-paid))}</p><button className="primary" onClick={sell}>إكمال وطباعة</button>{msg&&<div className="alert">{msg}</div>}</div></div><BarcodeScanner open={scannerOpen} onClose={()=>setScannerOpen(false)} onDetected={handleScan}/></section>}
