import Dexie,{Table} from 'dexie';
import type {AuditLog,Batch,Customer,Expense,Payment,Product,Purchase,PurchaseItem,Return,Sale,SaleItem,Settings,StockMovement,Supplier,User} from '../types/models';
class AlshifaaDB extends Dexie{
 products!:Table<Product,string>; batches!:Table<Batch,string>; customers!:Table<Customer,string>; suppliers!:Table<Supplier,string>; sales!:Table<Sale,string>; sale_items!:Table<SaleItem,string>; purchases!:Table<Purchase,string>; purchase_items!:Table<PurchaseItem,string>; expenses!:Table<Expense,string>; payments!:Table<Payment,string>; returns!:Table<Return,string>; stock_movements!:Table<StockMovement,string>; users!:Table<User,string>; settings!:Table<Settings,string>; audit_logs!:Table<AuditLog,string>;
 constructor(){super('ALSHIFAA_LOCAL_DB');this.version(1).stores({products:'id,pharmacy_id,arabic_name,english_name,generic_name,barcode,alternative_barcode,sku,manufacturer,active',batches:'id,pharmacy_id,product_id,batch_number,expiry_date,quantity',customers:'id,pharmacy_id,name,phone,balance',suppliers:'id,pharmacy_id,name,company,balance',sales:'id,pharmacy_id,invoice_no,created_at,customer_id,status',sale_items:'id,pharmacy_id,sale_id,product_id,batch_id',purchases:'id,pharmacy_id,invoice_no,date,supplier_id,status',purchase_items:'id,pharmacy_id,purchase_id,product_id,batch_id',expenses:'id,pharmacy_id,date,category',payments:'id,pharmacy_id,party_type,party_id,date',returns:'id,pharmacy_id,type,source_id,product_id',stock_movements:'id,pharmacy_id,product_id,batch_id,type,created_at',users:'id,pharmacy_id,username,email,role,active',settings:'id,pharmacy_id',audit_logs:'id,pharmacy_id,timestamp,action,entity'});}
}
export const db=new AlshifaaDB();
export const PHARMACY_ID_KEY='alshifaa_pharmacy_id';
export function getPharmacyId(){let id=localStorage.getItem(PHARMACY_ID_KEY); if(!id){id=crypto.randomUUID(); localStorage.setItem(PHARMACY_ID_KEY,id)} return id;}
export async function ensureBootstrap(){const pharmacy_id=getPharmacyId(); if(await db.settings.count()===0){await db.settings.add({id:'settings',pharmacy_id,created_at:new Date().toISOString(),updated_at:new Date().toISOString(),pharmacy_name:'اسم الصيدلية',currency:'SDG',currency_symbol:'ج.س',invoice_footer:'تم التشغيل بواسطة النجاح لإدارة الصيدليات — اتصال 0121164581 — واتساب 0969696787',default_paper:'80mm',tax_rate:0,offline_grace_days:7,session_timeout_minutes:30});} return pharmacy_id;}
