import type {User} from '../types/models'; import {downloadBackup,restoreBackup,exportCsv} from '../services/backup'; import {audit} from '../services/audit';
export default function Backup({user}:{user:User}){async function restore(e:any){const f=e.target.files?.[0]; if(!f)return; try{await restoreBackup(f); await audit(user.id,'restore','backup',f.name); alert('تمت استعادة النسخة الاحتياطية بنجاح')}catch(x:any){alert(x.message)}} async function csv(){const b=await exportCsv('products'); const a=document.createElement('a'); a.href=URL.createObjectURL(b); a.download='products.csv'; a.click()} return <section><h1>النسخ الاحتياطي والاستيراد/التصدير</h1><div className="card"><button onClick={async()=>{await downloadBackup(); await audit(user.id,'backup','backup')}}>تنزيل نسخة احتياطية كاملة</button><button onClick={csv}>تصدير المنتجات CSV</button><label className="upload">استعادة من ملف JSON<input hidden type="file" accept="application/json" onChange={restore}/></label><p>قبل الاستعادة يتم تجهيز نسخة أمان داخلية ولا يتم حذف بياناتك بصمت.</p></div></section>}
