import {useLiveQuery} from 'dexie-react-hooks'; import {db} from '../services/db'; import {useState} from 'react'; import {now,uid} from '../utils/ids';
export default function SimpleTablePage({table,title,creatable}:{table:string;title:string;creatable?:boolean}){const rows=useLiveQuery(()=>(db as any)[table].toArray(),[table])||[]; const [amount,setAmount]=useState(''); async function add(){ if(table==='expenses') await db.expenses.add({id:uid('exp'),pharmacy_id:localStorage.getItem('alshifaa_pharmacy_id')||'',created_at:now(),updated_at:now(),amount:+amount,date:now().slice(0,10),category:'أخرى',payment_method:'Cash'} as any); setAmount('')} return <section><h1>{title}</h1>{creatable&&<div className="card formgrid"><input type="number" value={amount} onChange={e=>setAmount(e.target.value)} placeholder="المبلغ"/><button onClick={add}>إضافة</button></div>}<div className="card"><table><tbody>{rows.map((r:any)=><tr key={r.id}>{Object.keys(r).slice(0,6).map(k=><td>{String(r[k]??'')}</td>)}</tr>)}</tbody></table>{!rows.length&&<p className="empty">لا توجد بيانات.</p>}</div></section>}
