import {NavLink,Route,Routes,Navigate} from 'react-router-dom'; import {useEffect,useState} from 'react'; import {currentUser,logout,usersCount} from './services/auth'; import type {User} from './types/models'; import Dashboard from './pages/Dashboard'; import POS from './pages/POS'; import SalesHistory from './pages/SalesHistory'; import Products from './pages/Products'; import Inventory from './pages/Inventory'; import Purchases from './pages/Purchases'; import People from './pages/People'; import SimpleTablePage from './pages/SimpleTablePage'; import Reports from './pages/Reports'; import Settings from './pages/Settings'; import License from './pages/License'; import Backup from './pages/Backup'; import Login from './pages/Login'; import Activation from './pages/Activation'; import SetupOwner from './pages/SetupOwner'; import {licenseGate} from './services/license'; import {db} from './services/db'; import {useLiveQuery} from 'dexie-react-hooks'; import ErrorBoundary from './components/ErrorBoundary'; import OfflineBadge from './components/OfflineBadge';
const nav=[['/','الرئيسية','▦'],['/pos','نقطة البيع','🛒'],['/sales','سجل المبيعات','▤'],['/products','المنتجات','◇'],['/inventory','المخزون','▣'],['/purchases','المشتريات','◈'],['/customers','العملاء','👥'],['/suppliers','الموردون','⌂'],['/returns','المرتجعات','↩'],['/expenses','المصروفات','◍'],['/payments','المدفوعات','▤'],['/reports','التقارير','≋'],['/users','المستخدمون','♙'],['/settings','الإعدادات','⚙'],['/license','الترخيص','⌁'],['/backup','النسخ الاحتياطي','⇩']];
export default function App(){const [user,setUser]=useState<User|null|undefined>(); const [hasUsers,setHasUsers]=useState<boolean|undefined>(); const [licenseTick,setLicenseTick]=useState(0); const settings=useLiveQuery(()=>db.settings.get('settings'),[]); useEffect(()=>{currentUser().then(setUser); usersCount().then(c=>setHasUsers(c>0))},[licenseTick]); if(user===undefined||hasUsers===undefined)return <div className="center">جاري التحميل...</div>; const gate=licenseGate(); if(!gate.ok && !hasUsers)return <Activation onActivated={()=>setLicenseTick(x=>x+1)}/>; if(gate.ok && !hasUsers)return <SetupOwner onDone={setUser} onExisting={()=>{setHasUsers(true); setUser(null)}}/>; if(!user)return <Login onLogin={setUser}/>; return <ErrorBoundary><div className="app"><aside><div className="brand"><img src="brand-logo.png" alt="النجاح"/><span>النجاح</span></div>{nav.map(([to,label,icon])=><NavLink key={to} to={to} end={to==='/'}><span className="nav-ico">{icon}</span><span>{label}</span></NavLink>)}<div className="provider-card"><b>النجاح لإدارة الصيدليات</b><span>الدعم والمبيعات</span><a href="tel:0121164581">اتصال: 0121164581</a><a href="https://wa.me/249969696787">واتساب: 0969696787</a></div><button className="ghost" onClick={()=>{logout();setUser(null)}}>تسجيل الخروج</button></aside><main><header><div className="page-title"><div className="header-client-logo">{settings?.logo?<img src={settings.logo} alt="شعار الصيدلية"/>:<img src="brand-logo.png" alt="النجاح"/>}</div><div><h2>{settings?.pharmacy_name&&settings.pharmacy_name!=='اسم الصيدلية'?settings.pharmacy_name:'النجاح لإدارة الصيدليات'}</h2><p>نظام إدارة وتشغيل الصيدليات</p></div></div><div className="header-actions"><OfflineBadge/><span className="user-chip">{user.name} — {user.role}</span></div></header><Routes><Route path="/" element={<Dashboard/>}/><Route path="/pos" element={<POS user={user}/>}/><Route path="/sales" element={<SalesHistory user={user}/>}/><Route path="/products" element={<Products user={user}/>}/><Route path="/inventory" element={<Inventory user={user}/>}/><Route path="/purchases" element={<Purchases user={user}/>}/><Route path="/customers" element={<People type="customers" user={user}/>}/><Route path="/suppliers" element={<People type="suppliers" user={user}/>}/><Route path="/returns" element={<SimpleTablePage table="returns" title="المرتجعات"/>}/><Route path="/expenses" element={<SimpleTablePage table="expenses" title="المصروفات" creatable/>}/><Route path="/payments" element={<SimpleTablePage table="payments" title="المدفوعات"/>}/><Route path="/reports" element={<Reports/>}/><Route path="/users" element={<SimpleTablePage table="users" title="المستخدمون"/>}/><Route path="/settings" element={<Settings/>}/><Route path="/license" element={<License/>}/><Route path="/backup" element={<Backup user={user}/>}/><Route path="*" element={<Navigate to="/"/>}/></Routes></main></div></ErrorBoundary>}
