import type {LicenseCache,LicenseStatus} from '../types/models';
const KEY='alshifaa_license_cache', DEVICE='alshifaa_device_fingerprint';
export async function getDeviceId(){ let id=localStorage.getItem(DEVICE)||''; const extra=[navigator.userAgent,screen.width,screen.height,navigator.language].join('|'); if(!id){const raw=crypto.randomUUID()+extra; const h=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(raw)); id=Array.from(new Uint8Array(h)).map(b=>b.toString(16).padStart(2,'0')).join(''); localStorage.setItem(DEVICE,id); try{await indexedDB.open('alshifaa_device_anchor',1)}catch{}} return id; }
export function getCachedLicense():LicenseCache|null{ const raw=localStorage.getItem(KEY); return raw?JSON.parse(raw):null; }
export function licenseGate(){ const l=getCachedLicense(); if(!l) return {ok:false,readOnly:true,message:'يرجى تفعيل الترخيص عبر الإنترنت أولاً'}; const now=Date.now(), exp=new Date(l.expires_at).getTime(), last=new Date(l.last_validation).getTime(); if(['SUSPENDED','REVOKED'].includes(l.status)) return {ok:false,readOnly:true,message:'الترخيص موقوف أو ملغي'}; if(l.status==='EXPIRED'||exp<now) return {ok:false,readOnly:true,message:'انتهت صلاحية الترخيص'}; if(now-last>l.grace_days*86400000) return {ok:false,readOnly:true,message:'انتهت مهلة العمل دون اتصال، يلزم التحقق عبر الإنترنت'}; return {ok:true,readOnly:false,message:navigator.onLine?'● متصل':'● غير متصل - يمكنك متابعة العمل'}; }
export async function validateLicense(endpoint:string, license_key:string){ const device_id=await getDeviceId(); const res=await fetch(`${endpoint.replace(/\/$/,'')}/functions/v1/license-check`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({license_key,device_id,product_code:'ALSHIFAA_ERP'})}); if(!res.ok) throw new Error('تعذر التحقق من الترخيص'); const data=await res.json(); if(!data.signature) throw new Error('استجابة ترخيص غير صالحة'); const cache:LicenseCache={...data,license_key,device_id,last_validation:new Date().toISOString(),last_seen:new Date().toISOString(),grace_days:data.grace_days??7,status:data.status as LicenseStatus}; localStorage.setItem(KEY,JSON.stringify(cache)); return cache; }
export function clearLicense(){localStorage.removeItem(KEY)}
