import { db, getPharmacyId } from './db'; import { now, uid } from '../utils/ids';
export async function audit(user:string, action:string, entity:string, entity_id?:string, details?:unknown){ await db.audit_logs.add({id:uid('audit'),pharmacy_id:getPharmacyId(),created_at:now(),updated_at:now(),timestamp:now(),user,action,entity,entity_id,details: typeof details==='string'?details:JSON.stringify(details??{})}); }
